/// Self-power-apply helper. Mirrors `silent.rs::apply_power_to_player`
/// (no cross-character helper sharing at this pin — bead
/// `sts2-rs-l0be`). Stacks additively on an existing instance.
pub(crate) fn apply_power_to_player(state: &mut CombatState, kind: PowerKind, amount: i32) {
    if amount <= 0 {
        return;
    }
    // Bead `sts2-rs-au4l2`: route through the canonical creature surface
    // when the d03 mirror is set, so self-powers stack onto the same
    // instance as relic combat-start grants.
    if let Some(uid) = state.player.creature_uid {
        sts2_core::card_effects::apply_power_to_creature(state, uid, kind, amount);
        return;
    }
    let existing_uid = state
        .player
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(uid) = existing_uid {
        if let Some(pow) = state.powers.get_mut_by_id(uid.0) {
            pow.amount = pow.amount.saturating_add(amount);
        }
        return;
    }
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = std::num::NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(new_id));
}

/// Apply a **signed** `amount` of `kind` to the player, creating a fresh
/// (possibly negative) instance when none exists. Mirrors the sibling pools'
/// `apply_power_signed_to_creature` (silent/ironclad/colorless) — the
/// canonical `apply_power_to_player` early-returns on `amount <= 0`, silently
/// dropping a negative apply. Needed for `AllowNegative` Counter powers
/// (Focus/Strength/Dexterity): C# `FocusPower.AllowNegative => true` and
/// `PowerModel.ShouldRemoveDueToAmount` removes such a power only at exactly
/// `Amount == 0`, so a negative apply must persist as a real instance.
/// Hyperbeam applies `Focus = -3` (C# `Hyperbeam.cs:57`).
pub(crate) fn apply_power_signed_to_player(state: &mut CombatState, kind: PowerKind, amount: i32) {
    if amount == 0 {
        return;
    }
    // Bead `sts2-rs-au4l2` (signed analogue): route through the canonical
    // creature surface when the d03 mirror is set, so a negative attribute
    // apply (Hyperbeam's Focus -3) stacks onto the SAME instance a prior
    // positive grant (Biased Cognition's Focus) created on the creature's
    // power list. The legacy `state.player.powers`-only search below misses
    // a creature-list instance and would push a second Focus power (sweep
    // `PLAYER_STATE|HYPERBEAM`: cs folds Focus 4->1, rs left Focus 4 + a
    // spurious Focus -3). `apply_signed_attr_power` uses the unioned
    // creature+player search and the same drop-at-0 policy as below.
    if let Some(uid) = state.player.creature_uid {
        sts2_core::card_effects::apply_signed_attr_power(state, uid, kind, amount);
        return;
    }
    // Stack into an existing instance when present (walking the mirror +
    // legacy player-power union), then drop only at exactly 0 to match C#
    // `PowerModel.ShouldRemoveDueToAmount` (`PowerModel.cs:413-424`).
    let existing_uid = state
        .player
        .powers
        .iter()
        .copied()
        .find(|uid| state.powers.iter().any(|p| p.id == uid.0 && p.kind == kind));
    if let Some(u) = existing_uid {
        let mut remove_pid = None;
        if let Some(pow) = state.powers.get_mut_by_id(u.0) {
            pow.amount = pow.amount.saturating_add(amount);
            if pow.amount == 0 {
                remove_pid = Some(u.0);
            }
        }
        if let Some(pid) = remove_pid {
            state.powers.retain(|p| p.id != pid);
            state.player.powers.retain(|x| x.0 != pid);
            for c in &mut state.creatures {
                c.powers.retain(|x| x.0 != pid);
            }
        }
        return;
    }
    // No instance: allocate a fresh one carrying the (possibly negative)
    // amount and link it onto the player. Route through the d03 mirror
    // creature when set (so later relic/card stacks land on the same
    // instance), with the legacy `state.player.powers` fallback otherwise.
    let next_id_raw = state
        .powers
        .iter()
        .map(|p| p.id.get())
        .max()
        .map_or(1, |m| m.saturating_add(1));
    let new_id = std::num::NonZeroU32::new(next_id_raw).expect("power id non-zero");
    state.powers.push(Power {
        id: new_id,
        kind,
        amount,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(PowerUid(new_id));
    if let Some(uid) = state.player.creature_uid {
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == uid.0) {
            c.powers.push(PowerUid(new_id));
        }
    }
}

