/// Deal `base` damage to every alive enemy.
pub(crate) fn deal_damage_player_to_all(state: &mut CombatState, base: i32) {
    let uids: Vec<CreatureUid> = state.enemy_uids.iter().copied().collect();
    for uid in uids {
        let alive = state
            .creatures
            .iter()
            .any(|c| c.id == uid.0 && c.current_hp > 0);
        if alive {
            let _ = deal_damage_player_to_enemy(state, uid, base);
        }
    }
}

/// The Defect 10-card starter deck: 4×StrikeDefect, 4×DefendDefect,
/// 1×Zap, 1×Dualcast. Mirrors C# `Defect.StartingDeck` (matched against
/// the run-parity C# oracle: `{STRIKEDEFECT:4, DEFENDDEFECT:4, ZAP:1,
/// DUALCAST:1}`). Closes GH#29: `starter_deck_for(Defect)` previously fell
/// back to the Ironclad starter, so every Defect run loaded the wrong
/// deck and diverged at the first event (`event/state/deck`, 50/50 in the
/// M6 sweep). Deck ORDER is non-load-bearing for parity (the lockstep
/// compares the master-deck multiset; combat shuffle randomizes), but the
/// Strike→Defend→Zap→Dualcast order mirrors the C# `StartingDeck` list.
#[must_use]
pub fn defect_starter_deck() -> Vec<CardSpec> {
    let mut deck = Vec::with_capacity(10);
    for _ in 0..4 {
        deck.push(super::strike_defect::spec());
    }
    for _ in 0..4 {
        deck.push(super::defend_defect::spec());
    }
    deck.push(super::zap::spec());
    deck.push(super::dualcast::spec());
    deck
}
